from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces in the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return not stack

    # Step 4: Return the list of distinct strings
    return [group for group in groups if is_balanced(group)]

